//! AbortSignal timeout uses actual native timer tasks, reasons and cancellation.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn fire(d:&mut Document,f:&mut Forms,p:&mut Page){let due=p.next_timer_deadline().expect("actual native timer deadline");let out=p.poll_timer_at(d,f,due).expect("actual native timer task");assert_eq!(out.errors,0,"{}",p.report());}
#[test]
fn abort_signal_timeout_zero_is_async_and_real_abort_event_reason_listener_cleanup_are_exact(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var descriptor=Object.getOwnPropertyDescriptor(AbortSignal,'timeout');if(typeof AbortSignal.timeout!=='function'||AbortSignal.timeout.length!==1||AbortSignal.timeout.name!=='timeout'||!descriptor.writable||!descriptor.enumerable||!descriptor.configurable)throw 'timeout static method';var s=AbortSignal.timeout(0),target=new EventTarget(),calls=0,reason,log='';target.addEventListener('linked',function(){throw 'linked listener survived timeout';},{signal:s});s.addEventListener('abort',function(e){if(!s.aborted||!(s.reason instanceof DOMException)||s.reason.name!=='TimeoutError'||s.reason.code!==23||e.target!==s||e.currentTarget!==s||e.eventPhase!==2||e.bubbles||e.cancelable||e.composed||!e.isTrusted||e.composedPath().length!==1||e.composedPath()[0]!==s)throw 'actual timeout event';reason=s.reason;var thrown;try{s.throwIfAborted();}catch(x){thrown=x;}if(thrown!==reason)throw 'throw exact reason';target.dispatchEvent(new Event('linked'));calls++;log+='A';Promise.resolve().then(function(){log+='P';document.title='timeout microtask';});},{once:true});if(s.aborted||s.reason!==undefined||s.throwIfAborted()!==undefined||calls||log)throw 'timeout must be asynchronous';
"#);fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==1||log!=='AP'||s.reason!==reason||!s.aborted)throw 'timeout final identity';");assert_eq!(d.title,"timeout microtask");assert!(p.next_timer_deadline().is_none());assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn abort_signal_timeout_enforce_range_conversion_is_once_and_has_no_signal_prefix_on_error(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"if(typeof AbortSignal.timeout!=='function')throw 'missing timeout';");let count=p.state.abort_signals.len();run(&mut d,&mut f,&mut p,r#"
var errors=0;for(var value of [-1,NaN,Infinity,-Infinity,18446744073709551616,9007199254740992,undefined,Symbol(),BigInt('1')]){try{AbortSignal.timeout(value);}catch(error){if(error instanceof TypeError)errors++;}}try{AbortSignal.timeout();}catch(error){if(error instanceof TypeError)errors++;}if(errors!==10)throw 'EnforceRange TypeErrors';var marker={},converted=0;try{AbortSignal.timeout({valueOf:function(){converted++;throw marker;}});}catch(error){if(error!==marker)throw 'abrupt numeric conversion';}if(converted!==1)throw 'conversion once';
"#);assert_eq!(p.state.abort_signals.len(),count);run(&mut d,&mut f,&mut p,r#"
var conversions=0,s=AbortSignal.timeout.call(null,{valueOf:function(){conversions++;return -0.9;}}),zero=AbortSignal.timeout(null),string=AbortSignal.timeout('0'),huge=AbortSignal.timeout(9007199254740991);if(conversions!==1||s.aborted||zero.aborted||string.aborted||huge.aborted||!(s instanceof AbortSignal)||s===zero)throw 'valid conversion and genuine identity';
"#);for _ in 0..3{fire(&mut d,&mut f,&mut p);}run(&mut d,&mut f,&mut p,"if(!s.aborted||!zero.aborted||!string.aborted||huge.aborted)throw 'converted timeout delivery';");}
#[test]
fn abort_signal_timeout_deadlines_order_actual_timer_tasks_and_do_not_fire_early(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var log='';function create(name,delay){var s=AbortSignal.timeout(delay);s.addEventListener('abort',function(){log+=name;});return s;}var a=create('A',20),b=create('B',0),c=create('C',10),d=create('D',0);if(log||a.aborted||b.aborted||c.aborted||d.aborted)throw 'no synchronous firing';
"#);let due=p.next_timer_deadline().unwrap();assert!(p.poll_timer_at(&mut d,&mut f,due-std::time::Duration::from_nanos(1)).is_none());for _ in 0..4{fire(&mut d,&mut f,&mut p);}run(&mut d,&mut f,&mut p,"if(log!=='BDCA'||!a.aborted||!b.aborted||!c.aborted||!d.aborted)throw 'actual timeout ordering';");assert!(p.next_timer_deadline().is_none());}
#[test]
fn abort_signal_timeout_child_owner_saved_factory_origin_and_disconnected_lifetime_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,factory=child.AbortSignal.timeout,ChildSignal=child.AbortSignal,ChildException=child.DOMException,s=factory(0),calls=0,conversions=0,arg={valueOf:function(){conversions++;return 0;}};if(!(s instanceof ChildSignal)||s instanceof AbortSignal||s.aborted)throw 'child signal owner';s.addEventListener('abort',function(e){if(!(s.reason instanceof ChildException)||s.reason instanceof DOMException||e.target!==s||!e.isTrusted)throw 'child timeout reason owner';calls++;});document.body;
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());let count=p.state.abort_signals.len();p.begin_job();let error=p.runtime.execute("factory(arg)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.abort_signals.len(),count);p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==1||conversions)throw 'origin refusal prefix and fresh task recovery';var stopped=factory(0);stopped.addEventListener('abort',function(){throw 'disconnected timeout delivered';});frame.remove();");let due=p.next_timer_deadline().unwrap();assert_eq!(p.poll_timer_at(&mut d,&mut f,due).unwrap().errors,0);run(&mut d,&mut f,&mut p,"if(stopped.aborted||stopped.reason!==undefined)throw 'disconnected timeout fabricated abort';var fresh=AbortSignal.timeout(0);fresh.addEventListener('abort',function(){calls++;});");fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==2||!fresh.aborted)throw 'main timeout recovery';");}
#[test]
fn abort_signal_timeout_factory_and_delivery_refusals_leave_no_abort_prefix_and_recover(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"if(typeof AbortSignal.timeout!=='function')throw 'missing timeout';new AbortController();");while p.state.abort_signals.len()<p.state.abort_signals.capacity(){run(&mut d,&mut f,&mut p,"new AbortController();");}let before=(p.state.retained,p.state.abort_signals.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("AbortSignal.timeout(0)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.abort_signals.len()),before);assert!(p.next_timer_deadline().is_none());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var recovered=AbortSignal.timeout(0);");fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(!recovered.aborted||recovered.reason.name!=='TimeoutError')throw 'factory fresh recovery';");}
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var s=AbortSignal.timeout(0),calls=0;s.addEventListener('abort',function(){calls++;});");let before=(p.state.retained,p.state.abort_signals.len(),p.state.listeners.len());let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained;let due=p.next_timer_deadline().unwrap();assert_eq!(p.poll_timer_at(&mut d,&mut f,due).unwrap().errors,1);assert_eq!((p.state.retained,p.state.abort_signals.len(),p.state.listeners.len()),before);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.next_timer_deadline().is_none());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(s.aborted||s.reason!==undefined||calls)throw 'delivery refusal prefix';var fresh=AbortSignal.timeout(0);fresh.addEventListener('abort',function(){calls++;});");fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==1||!fresh.aborted||s.aborted)throw 'delivery fresh recovery';");}
#[test]
fn abort_signal_timeout_explicit_timer_stop_cancels_pending_native_work_without_fabricating_abort(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var s=AbortSignal.timeout(0),calls=0;s.addEventListener('abort',function(){calls++;});");assert!(p.next_timer_deadline().is_some());p.stop_timers("explicit timer stop");assert!(p.next_timer_deadline().is_none());assert!(p.poll_timer_at(&mut d,&mut f,Instant::now()+std::time::Duration::from_secs(1)).is_none());run(&mut d,&mut f,&mut p,"if(s.aborted||s.reason!==undefined||calls)throw 'stopped timeout fabricated abort';var fresh=AbortSignal.timeout(0);fresh.addEventListener('abort',function(){calls++;});");fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==1||!fresh.aborted||s.aborted)throw 'stop fresh recovery';");}
